(function () {
	'use strict';

	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;

	var store = {
		todos: [],
		nextId: 1,

		load: function () {
			try {
				var data = localStorage.getItem('todos-vanillajs');
				if (data) {
					var parsed = JSON.parse(data);
					this.todos = parsed.todos || [];
					this.nextId = parsed.nextId || 1;
				}
			} catch (e) {
				this.todos = [];
				this.nextId = 1;
			}
		},

		save: function () {
			try {
				localStorage.setItem('todos-vanillajs', JSON.stringify({
					todos: this.todos,
					nextId: this.nextId
				}));
			} catch (e) {
				// localStorage full or unavailable
			}
		},

		add: function (title) {
			var todo = {
				id: this.nextId++,
				title: title,
				completed: false
			};
			this.todos.push(todo);
			this.save();
			return todo;
		},

		toggle: function (id) {
			var todo = this.findById(id);
			if (todo) {
				todo.completed = !todo.completed;
				this.save();
			}
		},

		toggleAll: function (completed) {
			this.todos.forEach(function (todo) {
				todo.completed = completed;
			});
			this.save();
		},

		update: function (id, title) {
			var todo = this.findById(id);
			if (todo) {
				todo.title = title;
				this.save();
			}
		},

		destroy: function (id) {
			this.todos = this.todos.filter(function (todo) {
				return todo.id !== id;
			});
			this.save();
		},

		clearCompleted: function () {
			this.todos = this.todos.filter(function (todo) {
				return !todo.completed;
			});
			this.save();
		},

		findById: function (id) {
			for (var i = 0; i < this.todos.length; i++) {
				if (this.todos[i].id === id) {
					return this.todos[i];
				}
			}
			return null;
		},

		getFiltered: function (filter) {
			return this.todos.filter(function (todo) {
				if (filter === 'active') {
					return !todo.completed;
				}
				if (filter === 'completed') {
					return todo.completed;
				}
				return true;
			});
		},

		getActiveCount: function () {
			var count = 0;
			this.todos.forEach(function (todo) {
				if (!todo.completed) {
					count++;
				}
			});
			return count;
		},

		getCompletedCount: function () {
			var count = 0;
			this.todos.forEach(function (todo) {
				if (todo.completed) {
					count++;
				}
			});
			return count;
		}
	};

	var app = {
		currentFilter: 'all',

		init: function () {
			store.load();
			this.bindEvents();
			this.render();
			this.handleRoute();
		},

		bindEvents: function () {
			var newTodoInput = document.querySelector('.new-todo');
			var todoList = document.querySelector('.todo-list');
			var toggleAll = document.querySelector('#toggle-all');
			var clearCompleted = document.querySelector('.clear-completed');

			newTodoInput.addEventListener('keydown', this.handleNewTodoKeydown.bind(this));
			todoList.addEventListener('click', this.handleTodoListClick.bind(this));
			todoList.addEventListener('dblclick', this.handleTodoListDblClick.bind(this));
			todoList.addEventListener('focusout', this.handleTodoListFocusOut.bind(this));
			todoList.addEventListener('keydown', this.handleTodoListKeydown.bind(this));
			toggleAll.addEventListener('change', this.handleToggleAll.bind(this));
			clearCompleted.addEventListener('click', this.handleClearCompleted.bind(this));
			window.addEventListener('hashchange', this.handleRoute.bind(this));
		},

		handleNewTodoKeydown: function (e) {
			if (e.keyCode !== ENTER_KEY) {
				return;
			}
			var input = e.target;
			var title = input.value.trim();
			if (title) {
				store.add(title);
				input.value = '';
				this.render();
			}
		},

		handleTodoListClick: function (e) {
			var target = e.target;
			if (target.classList.contains('toggle')) {
				var li = target.closest('li');
				var id = this.getTodoId(li);
				store.toggle(id);
				var todo = store.findById(id);
				if (todo) {
					if (this.shouldShowTodo(todo)) {
						if (todo.completed) {
							li.classList.add('completed');
						} else {
							li.classList.remove('completed');
						}
						target.checked = todo.completed;
					} else {
						li.parentNode.removeChild(li);
					}
				}
				this.renderFooter();
				this.renderToggleAll();
			} else if (target.classList.contains('destroy')) {
				var li = target.closest('li');
				var id = this.getTodoId(li);
				store.destroy(id);
				this.render();
			}
		},

		handleTodoListDblClick: function (e) {
			if (e.target.tagName !== 'LABEL') {
				return;
			}
			var li = e.target.closest('li');
			li.classList.add('editing');
			var editInput = li.querySelector('.edit');
			editInput.value = e.target.textContent;
			editInput.focus();
		},

		handleTodoListFocusOut: function (e) {
			if (!e.target.classList.contains('edit')) {
				return;
			}
			var li = e.target.closest('li');
			if (!li.classList.contains('editing')) {
				return;
			}
			this.saveEdit(li, e.target);
		},

		handleTodoListKeydown: function (e) {
			if (e.target.classList.contains('edit')) {
				if (e.keyCode === ENTER_KEY) {
					var li = e.target.closest('li');
					this.saveEdit(li, e.target);
				} else if (e.keyCode === ESCAPE_KEY) {
					var li = e.target.closest('li');
					li.classList.remove('editing');
				}
			}
		},

		saveEdit: function (li, editInput) {
			var id = this.getTodoId(li);
			var title = editInput.value.trim();
			if (title) {
				store.update(id, title);
			} else {
				store.destroy(id);
			}
			li.classList.remove('editing');
			this.render();
		},

		handleToggleAll: function (e) {
			var completed = e.target.checked;
			store.toggleAll(completed);
			var allLis = document.querySelectorAll('.todo-list li');
			allLis.forEach(function (li) {
				var id = this.getTodoId(li);
				var todo = store.findById(id);
				if (todo) {
					if (this.shouldShowTodo(todo)) {
						if (completed) {
							li.classList.add('completed');
						} else {
							li.classList.remove('completed');
						}
						var checkbox = li.querySelector('.toggle');
						if (checkbox) checkbox.checked = completed;
					} else {
						li.parentNode.removeChild(li);
					}
				}
			}.bind(this));
			this.renderFooter();
		},

		handleClearCompleted: function () {
			store.clearCompleted();
			this.render();
		},

		handleRoute: function () {
			var hash = window.location.hash || '#/';
			if (hash === '#/active') {
				this.currentFilter = 'active';
			} else if (hash === '#/completed') {
				this.currentFilter = 'completed';
			} else {
				this.currentFilter = 'all';
			}
			this.render();
		},

		getTodoId: function (li) {
			return parseInt(li.getAttribute('data-id'), 10);
		},

		shouldShowTodo: function (todo) {
			if (this.currentFilter === 'active') {
				return !todo.completed;
			}
			if (this.currentFilter === 'completed') {
				return todo.completed;
			}
			return true;
		},

		render: function () {
			this.renderTodoList();
			this.renderFooter();
			this.renderToggleAll();
		},

		renderTodoList: function () {
			var todoList = document.querySelector('.todo-list');
			var todos = store.getFiltered(this.currentFilter);
			var html = '';

			todos.forEach(function (todo) {
				var completedClass = todo.completed ? ' completed' : '';
				html += '<li class="' + completedClass + '" data-id="' + todo.id + '">';
				html += '<div class="view">';
				html += '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>';
				html += '<label>' + this.escapeHtml(todo.title) + '</label>';
				html += '<button class="destroy"></button>';
				html += '</div>';
				html += '<input class="edit" value="' + this.escapeHtml(todo.title) + '">';
				html += '</li>';
			}.bind(this));

			todoList.innerHTML = html;
		},

		escapeHtml: function (text) {
			var div = document.createElement('div');
			div.textContent = text;
			return div.innerHTML;
		},

		renderFooter: function () {
			var footer = document.querySelector('.footer');
			var activeCount = store.getActiveCount();
			var completedCount = store.getCompletedCount();
			var todoCount = document.querySelector('.todo-count');
			var clearCompleted = document.querySelector('.clear-completed');

			if (store.todos.length === 0) {
				footer.style.display = 'none';
				return;
			}

			footer.style.display = '';
			var itemText = activeCount === 1 ? 'item' : 'items';
			todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + itemText + ' left';

			if (completedCount > 0) {
				clearCompleted.style.display = '';
			} else {
				clearCompleted.style.display = 'none';
			}

			var filterLinks = document.querySelectorAll('.filters a');
			filterLinks.forEach(function (link) {
				link.classList.remove('selected');
			});

			if (this.currentFilter === 'active') {
				document.querySelector('.filters a[href="#/active"]').classList.add('selected');
			} else if (this.currentFilter === 'completed') {
				document.querySelector('.filters a[href="#/completed"]').classList.add('selected');
			} else {
				document.querySelector('.filters a[href="#/"]').classList.add('selected');
			}
		},

		renderToggleAll: function () {
			var toggleAll = document.querySelector('#toggle-all');
			var main = document.querySelector('.main');

			if (store.todos.length === 0) {
				main.style.display = 'none';
				return;
			}

			main.style.display = '';
			var allCompleted = store.getActiveCount() === 0 && store.todos.length > 0;
			toggleAll.checked = allCompleted;
		}
	};

	app.init();
})();

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

