(function () {
	'use strict';

	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;

	var store = {
		todos: [],
		nextId: 1,

		load: function () {
			try {
				var data = localStorage.getItem('todos-vanillajs');
				if (data) {
					var parsed = JSON.parse(data);
					this.todos = parsed.todos || [];
					this.nextId = parsed.nextId || 1;
				}
			} catch (e) {
				this.todos = [];
				this.nextId = 1;
			}
		},

		save: function () {
			try {
				localStorage.setItem('todos-vanillajs', JSON.stringify({
					todos: this.todos,
					nextId: this.nextId
				}));
			} catch (e) {
				// localStorage full or unavailable
			}
		},

		add: function (title) {
			var todo = {
				id: this.nextId++,
				title: title,
				completed: false
			};
			this.todos.push(todo);
			this.save();
			return todo;
		},

		toggle: function (id) {
			var todo = this.findById(id);
			if (todo) {
				todo.completed = !todo.completed;
				this.save();
			}
		},

		toggleAll: function (completed) {
			this.todos.forEach(function (todo) {
				todo.completed = completed;
			});
			this.save();
		},

		update: function (id, title) {
			var todo = this.findById(id);
			if (todo) {
				todo.title = title;
				this.save();
			}
		},

		destroy: function (id) {
			this.todos = this.todos.filter(function (todo) {
				return todo.id !== id;
			});
			this.save();
		},

		clearCompleted: function () {
			this.todos = this.todos.filter(function (todo) {
				return !todo.completed;
			});
			this.save();
		},

		findById: function (id) {
			for (var i = 0; i < this.todos.length; i++) {
				if (this.todos[i].id === id) {
					return this.todos[i];
				}
			}
			return null;
		},

		getFiltered: function (filter) {
			return this.todos.filter(function (todo) {
				if (filter === 'active') {
					return !todo.completed;
				}
				if (filter === 'completed') {
					return todo.completed;
				}
				return true;
			});
		},

		getActiveCount: function () {
			var count = 0;
			this.todos.forEach(function (todo) {
				if (!todo.completed) {
					count++;
				}
			});
			return count;
		},

		getCompletedCount: function () {
			var count = 0;
			this.todos.forEach(function (todo) {
				if (todo.completed) {
					count++;
				}
			});
			return count;
		}
	};

	var app = {
		currentFilter: 'all',

		init: function () {
			store.load();
			this.bindEvents();
			this.render();
			this.handleRoute();
		},

		bindEvents: function () {
			var newTodoInput = document.querySelector('.new-todo');
			var todoList = document.querySelector('.todo-list');
			var toggleAll = document.querySelector('#toggle-all');
			var clearCompleted = document.querySelector('.clear-completed');

			newTodoInput.addEventListener('keydown', this.handleNewTodoKeydown.bind(this));
			todoList.addEventListener('click', this.handleTodoListClick.bind(this));
			todoList.addEventListener('change', this.handleTodoListChange.bind(this));
			todoList.addEventListener('dblclick', this.handleTodoListDblClick.bind(this));
			todoList.addEventListener('focusout', this.handleTodoListFocusOut.bind(this));
			todoList.addEventListener('keydown', this.handleTodoListKeydown.bind(this));
			toggleAll.addEventListener('change', this.handleToggleAll.bind(this));
			clearCompleted.addEventListener('click', this.handleClearCompleted.bind(this));
			window.addEventListener('hashchange', this.handleRoute.bind(this));
		},

		handleNewTodoKeydown: function (e) {
			if (e.keyCode !== ENTER_KEY) {
				return;
			}
			var input = e.target;
			var title = input.value.trim();
			if (title) {
				store.add(title);
				input.value = '';
				this.render();
			}
		},

		handleTodoListClick: function (e) {
			var target = e.target;
			if (target.classList.contains('toggle')) {
				// Prevent the browser's native checkbox toggle when clicking directly on it.
				// The change event handler will process the toggle instead.
				e.preventDefault();
			} else if (target.classList.contains('destroy')) {
				var li = target.closest('li');
				var id = this.getTodoId(li);
				store.destroy(id);
				this.render();
			}
		},

		handleTodoListChange: function (e) {
			var target = e.target;
			if (!target.classList.contains('toggle')) {
				return;
			}
			var li = target.closest('li');
			var id = this.getTodoId(li);
			store.toggle(id);
			var todo = store.findById(id);
			if (todo) {
				if (this.shouldShowTodo(todo)) {
					if (todo.completed) {
						li.classList.add('completed');
					} else {
						li.classList.remove('completed');
					}
					target.checked = todo.completed;
				} else {
					li.parentNode.removeChild(li);
				}
			}
			this.renderFooter();
			this.renderToggleAll();
		},

		handleTodoListDblClick: function (e) {
			if (e.target.tagName !== 'LABEL') {
				return;
			}
			var li = e.target.closest('li');
			li.classList.add('editing');
			var editInput = li.querySelector('.edit');
			editInput.value = e.target.textContent;
			editInput.focus();
		},

		handleTodoListFocusOut: function (e) {
			if (!e.target.classList.contains('edit')) {
				return;
			}
			var li = e.target.closest('li');
			if (!li.classList.contains('editing')) {
				return;
			}
			this.saveEdit(li, e.target);
		},

		handleTodoListKeydown: function (e) {
			if (e.target.classList.contains('edit')) {
				if (e.keyCode === ENTER_KEY) {
					var li = e.target.closest('li');
					this.saveEdit(li, e.target);
				} else if (e.keyCode === ESCAPE_KEY) {
					var li = e.target.closest('li');
					li.classList.remove('editing');
				}
			}
		},

		saveEdit: function (li, editInput) {
			var id = this.getTodoId(li);
			var title = editInput.value.trim();
			if (title) {
				store.update(id, title);
			} else {
				store.destroy(id);
			}
			li.classList.remove('editing');
			this.render();
		},

		handleToggleAll: function (e) {
			var completed = e.target.checked;
			store.toggleAll(completed);
			var allLis = document.querySelectorAll('.todo-list li');
			allLis.forEach(function (li) {
				var id = this.getTodoId(li);
				var todo = store.findById(id);
				if (todo) {
					if (this.shouldShowTodo(todo)) {
						if (completed) {
							li.classList.add('completed');
						} else {
							li.classList.remove('completed');
						}
						var checkbox = li.querySelector('.toggle');
						if (checkbox) checkbox.checked = completed;
					} else {
						li.parentNode.removeChild(li);
					}
				}
			}.bind(this));
			this.renderFooter();
		},

		handleClearCompleted: function () {
			store.clearCompleted();
			this.render();
		},

		handleRoute: function () {
			var hash = window.location.hash || '#/';
			if (hash === '#/active') {
				this.currentFilter = 'active';
			} else if (hash === '#/completed') {
				this.currentFilter = 'completed';
			} else {
				this.currentFilter = 'all';
			}
			this.render();
		},

		getTodoId: function (li) {
			return parseInt(li.getAttribute('data-id'), 10);
		},

		shouldShowTodo: function (todo) {
			if (this.currentFilter === 'active') {
				return !todo.completed;
			}
			if (this.currentFilter === 'completed') {
				return todo.completed;
			}
			return true;
		},

		render: function () {
			this.renderTodoList();
			this.renderFooter();
			this.renderToggleAll();
		},

		renderTodoList: function () {
			var todoList = document.querySelector('.todo-list');
			var todos = store.getFiltered(this.currentFilter);
			var html = '';

			todos.forEach(function (todo) {
				var completedClass = todo.completed ? ' completed' : '';
				html += '<li class="' + completedClass + '" data-id="' + todo.id + '">';
				html += '<div class="view">';
				html += '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>';
				html += '<label>' + this.escapeHtml(todo.title) + '</label>';
				html += '<button class="destroy"></button>';
				html += '</div>';
				html += '<input class="edit" value="' + this.escapeHtml(todo.title) + '">';
				html += '</li>';
			}.bind(this));

			todoList.innerHTML = html;
		},

		escapeHtml: function (text) {
			var div = document.createElement('div');
			div.textContent = text;
			return div.innerHTML;
		},

		renderFooter: function () {
			var footer = document.querySelector('.footer');
			var activeCount = store.getActiveCount();
			var completedCount = store.getCompletedCount();
			var todoCount = document.querySelector('.todo-count');
			var clearCompleted = document.querySelector('.clear-completed');

			if (store.todos.length === 0) {
				footer.style.display = 'none';
				return;
			}

			footer.style.display = '';
			var itemText = activeCount === 1 ? 'item' : 'items';
			todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + itemText + ' left';

			if (completedCount > 0) {
				clearCompleted.style.display = '';
			} else {
				clearCompleted.style.display = 'none';
			}

			var filterLinks = document.querySelectorAll('.filters a');
			filterLinks.forEach(function (link) {
				link.classList.remove('selected');
			});

			if (this.currentFilter === 'active') {
				document.querySelector('.filters a[href="#/active"]').classList.add('selected');
			} else if (this.currentFilter === 'completed') {
				document.querySelector('.filters a[href="#/completed"]').classList.add('selected');
			} else {
				document.querySelector('.filters a[href="#/"]').classList.add('selected');
			}
		},

		renderToggleAll: function () {
			var toggleAll = document.querySelector('#toggle-all');
			var main = document.querySelector('.main');

			if (store.todos.length === 0) {
				main.style.display = 'none';
				return;
			}

			main.style.display = '';
			var allCompleted = store.getActiveCount() === 0 && store.todos.length > 0;
			toggleAll.checked = allCompleted;
		}
	};

	app.init();
})();

